<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Snake</title>
<style>
  :root{
    --bg:#070a08; --panel:#0c110d; --frame:#0a0f0b;
    --line:#1c251f; --line2:#2b382e;
    --ink:#e7f4e6; --mid:#c2d8c3; --dim:#7c9180; --faint:#5a6b5e;
    --accent:#8ee08a; --bright:#c8f7b8; --coral:#ff6b52; --amber:#e6c47a;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%}
  body{
    background:var(--bg); color:var(--ink);
    font-family:ui-monospace,'SF Mono',Menlo,Consolas,'Liberation Mono',monospace;
    display:flex; align-items:center; justify-content:center;
    min-height:100vh; padding:28px 16px;
  }
  .wrap{width:440px;display:flex;flex-direction:column;gap:14px}
  .top{display:flex;justify-content:space-between;align-items:flex-end}
  h1{font-size:19px;font-weight:700;letter-spacing:.42em;color:var(--ink);line-height:1}
  h1::before{content:'';display:inline-block;width:11px;height:11px;border-radius:3px;background:var(--accent);margin-right:13px;vertical-align:1px}
  .status{margin-top:8px;display:flex;align-items:center;gap:8px;font-size:11px;letter-spacing:.2em;color:var(--dim)}
  .dot{width:7px;height:7px;border-radius:50%;background:#8aa08c;flex:none}
  .dot.running{background:var(--accent);animation:blink 1.15s steps(1) infinite}
  .dot.paused{background:var(--amber)}
  .dot.over{background:var(--coral)}
  .dot.win{background:var(--bright)}
  @keyframes blink{50%{opacity:.3}}
  .scorebox{text-align:right}
  .scorebox .label{display:block;font-size:10px;letter-spacing:.34em;color:var(--dim);margin-bottom:3px}
  #score{display:inline-block;font-size:33px;font-weight:700;line-height:1;color:var(--bright);font-variant-numeric:tabular-nums}
  #score.pop{animation:pop .32s ease}
  @keyframes pop{35%{transform:scale(1.32);color:#b6ff8f}}
  .board{padding:8px;background:var(--frame);border:1px solid var(--line);border-radius:14px}
  #snake{display:block;width:440px;height:440px;background:var(--panel);border-radius:8px}
  .controls{display:flex;gap:10px}
  button{
    flex:1;font:inherit;font-size:12px;font-weight:700;letter-spacing:.24em;text-transform:uppercase;
    padding:12px 0 11px;color:var(--mid);background:#0e140f;border:1px solid var(--line2);border-radius:9px;cursor:pointer;
    transition:background .15s,border-color .15s,color .15s,opacity .15s;
  }
  button:hover:not(:disabled){background:#16211a;border-color:#3d4f41;color:var(--ink)}
  button:active:not(:disabled){transform:translateY(1px)}
  button:disabled{opacity:.35;cursor:default}
  #start{border-color:#35502f;color:var(--accent)}
  #start:hover:not(:disabled){border-color:#4d7a46;background:#13200f;color:var(--bright)}
  .hint{text-align:center;font-size:11px;color:var(--faint);letter-spacing:.06em}
  .hint kbd{display:inline-block;min-width:20px;padding:2px 5px 1px;margin:0 1px;border:1px solid var(--line2);border-bottom-width:2px;border-radius:4px;background:#0e140f;color:#93ab94;font-size:10px;text-align:center}
</style>
</head>
<body>
<main class="wrap">
  <header class="top">
    <div>
      <h1>SNAKE</h1>
      <div class="status"><span class="dot"></span><span id="status">READY</span></div>
    </div>
    <div class="scorebox">
      <span class="label">SCORE</span>
      <span id="score">0</span>
    </div>
  </header>
  <div class="board"><canvas id="snake" width="440" height="440"></canvas></div>
  <div class="controls">
    <button id="start">Start</button>
    <button id="pause" disabled>Pause</button>
    <button id="reset">Reset</button>
  </div>
  <p class="hint"><kbd>↑</kbd><kbd>↓</kbd><kbd>←</kbd><kbd>→</kbd> steer &nbsp;·&nbsp; <kbd>Space</kbd> pause &nbsp;·&nbsp; <kbd>Enter</kbd> start</p>
</main>

<script>
(function(){
'use strict';

/* ---------- constants ---------- */
var COLS = 20, ROWS = 20, CELL = 22, SIZE = COLS * CELL;   // 440 x 440 board
var MONO = 'ui-monospace, Menlo, Consolas, monospace';
var DIRS = {up:{x:0,y:-1}, down:{x:0,y:1}, left:{x:-1,y:0}, right:{x:1,y:0}};
var OPP  = {up:'down', down:'up', left:'right', right:'left'};

/* ---------- canvas ---------- */
var cv  = document.getElementById('snake');
var ctx = cv.getContext('2d');
var dpr = 1;
function fit(){
  dpr = Math.max(1, window.devicePixelRatio || 1);
  cv.width  = SIZE * dpr;
  cv.height = SIZE * dpr;
}
fit();
window.addEventListener('resize', fit);

/* ---------- state ---------- */
var S = {
  snake:[], prev:[], dir:'right', queue:[],
  food:null, alive:true, score:0,
  running:false, everStarted:false, won:false,
  lastTick:0, deathAt:0, effects:[]
};

/* ---------- dom ---------- */
var scoreEl  = document.getElementById('score');
var statusEl = document.getElementById('status');
var dotEl    = document.querySelector('.dot');
var startBtn = document.getElementById('start');
var pauseBtn = document.getElementById('pause');
var resetBtn = document.getElementById('reset');

/* ---------- core logic ---------- */
function tickInterval(){ return Math.max(65, 132 - S.score * 3); }

function spawnFood(){
  var occ = new Set(S.snake.map(function(s){ return s.x + ',' + s.y; }));
  var free = [];
  for (var y = 0; y < ROWS; y++)
    for (var x = 0; x < COLS; x++)
      if (!occ.has(x + ',' + y)) free.push({x:x, y:y});
  if (!free.length){ S.food = null; S.won = true; S.running = false; syncUI(); return; }
  S.food = free[Math.floor(Math.random() * free.length)];
}

function reset(){
  S.snake = [];
  var cx = COLS >> 1, cy = ROWS >> 1;
  for (var i = 0; i < 4; i++) S.snake.push({x: cx - i, y: cy});   // length 4, heading right
  S.prev = S.snake.map(function(s){ return {x:s.x, y:s.y}; });
  S.dir = 'right'; S.queue = [];
  S.alive = true; S.score = 0;
  S.running = false; S.everStarted = false; S.won = false;
  S.deathAt = 0; S.effects = [];
  spawnFood();
  S.lastTick = performance.now();
  updateScore(false); syncUI();
  draw(performance.now());
}

function die(){
  S.alive = false; S.running = false;
  S.deathAt = performance.now();
  syncUI();
}

function tick(){
  if (!S.alive || S.won) return;
  if (S.queue.length) S.dir = S.queue.shift();
  var d = DIRS[S.dir], h = S.snake[0];
  var nx = h.x + d.x, ny = h.y + d.y;

  // wall
  if (nx < 0 || ny < 0 || nx >= COLS || ny >= ROWS){ die(); return; }
  // own body
  for (var i = 0; i < S.snake.length; i++){
    if (S.snake[i].x === nx && S.snake[i].y === ny){ die(); return; }
  }

  S.prev = S.snake.map(function(s){ return {x:s.x, y:s.y}; });
  S.snake.unshift({x:nx, y:ny});

  if (S.food && nx === S.food.x && ny === S.food.y){
    S.score++;                                  // grow: tail is NOT popped
    S.effects.push({x:nx, y:ny, t:performance.now()});
    spawnFood();
    updateScore(true);
  } else {
    S.snake.pop();
  }
  S.lastTick = performance.now();
  draw(performance.now());
}

function setDir(d){
  if (!DIRS[d] || !S.alive) return;
  var last = S.queue.length ? S.queue[S.queue.length - 1] : S.dir;
  if (d === last || OPP[d] === last) return;    // same heading or 180° reversal -> ignored
  if (S.queue.length < 3) S.queue.push(d);
}

function setFood(x, y){
  S.food = {x:x, y:y};
  if (S.won){ S.won = false; syncUI(); }
  draw(performance.now());
}

function start(){
  if (!S.alive || S.won) reset();
  S.everStarted = true; S.running = true;
  S.lastTick = performance.now();
  syncUI();
}
function pause(){ S.running = false; syncUI(); }

/* ---------- ui ---------- */
function updateScore(pop){
  scoreEl.textContent = S.score;
  if (pop){
    scoreEl.classList.remove('pop');
    void scoreEl.offsetWidth;
    scoreEl.classList.add('pop');
  }
}

function syncUI(){
  var st, cls;
  if (!S.alive)      { st = 'GAME OVER'; cls = 'over'; }
  else if (S.won)    { st = 'YOU WIN';   cls = 'win'; }
  else if (S.running){ st = 'RUNNING';   cls = 'running'; }
  else if (S.everStarted){ st = 'PAUSED'; cls = 'paused'; }
  else               { st = 'READY';     cls = 'ready'; }
  statusEl.textContent = st;
  dotEl.className = 'dot ' + cls;
  startBtn.disabled = S.running;
  pauseBtn.disabled = !S.running;
}

/* ---------- drawing ---------- */
function lerp(a, b, t){ return a + (b - a) * t; }
function mix(c1, c2, t){
  return 'rgb(' + Math.round(lerp(c1[0], c2[0], t)) + ',' +
                  Math.round(lerp(c1[1], c2[1], t)) + ',' +
                  Math.round(lerp(c1[2], c2[2], t)) + ')';
}
function sp(s){ return s.split('').join(' '); }
function text(str, y, size, color, weight){
  ctx.font = (weight || 700) + ' ' + size + 'px ' + MONO;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillStyle = color;
  ctx.fillText(str, SIZE / 2, y);
}
function rr(x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function drawFood(now){
  var cx = (S.food.x + 0.5) * CELL, cy = (S.food.y + 0.5) * CELL;
  var r = CELL * 0.30 * (1 + 0.10 * Math.sin(now / 260));
  ctx.beginPath(); ctx.arc(cx, cy, r + 4.5, 0, Math.PI * 2);
  ctx.strokeStyle = 'rgba(255,107,82,0.30)'; ctx.lineWidth = 1.5; ctx.stroke();
  ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fillStyle = '#ff6b52'; ctx.fill();
  ctx.beginPath(); ctx.arc(cx - r * 0.32, cy - r * 0.34, r * 0.27, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255,238,224,0.55)'; ctx.fill();
}

function drawSnake(now){
  var n = S.snake.length;
  var t = (S.running && S.alive && !S.won)
          ? Math.min(1, (now - S.lastTick) / tickInterval()) : 1;
  var pts = [];
  for (var i = 0; i < n; i++){
    var c = S.snake[i];
    var p = S.prev[i] || S.prev[S.prev.length - 1] || c;
    pts.push({ x: (lerp(p.x, c.x, t) + 0.5) * CELL,
               y: (lerp(p.y, c.y, t) + 0.5) * CELL });
  }
  var dead = !S.alive;
  var hC = dead ? [255,143,118] : [216,255,186];
  var tC = dead ? [99,50,43]    : [50,122,85];

  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  for (var j = n - 1; j >= 1; j--){                 // tail first, head paints on top
    var f = j / Math.max(1, n - 1);
    ctx.strokeStyle = mix(hC, tC, f);
    ctx.lineWidth = CELL * (0.74 - 0.26 * f);       // gentle taper toward the tail
    ctx.beginPath();
    ctx.moveTo(pts[j].x, pts[j].y);
    ctx.lineTo(pts[j - 1].x, pts[j - 1].y);
    ctx.stroke();
  }

  // head + eyes
  var hp = pts[0], dx, dy;
  if (n > 1){ dx = hp.x - pts[1].x; dy = hp.y - pts[1].y; }
  else { var dd = DIRS[S.dir]; dx = dd.x; dy = dd.y; }
  var L = Math.hypot(dx, dy) || 1, ux = dx / L, uy = dy / L;
  ctx.beginPath(); ctx.arc(hp.x, hp.y, CELL * 0.44, 0, Math.PI * 2);
  ctx.fillStyle = dead ? '#ff9d86' : '#eaffd8'; ctx.fill();
  var px = -uy, py = ux, er = CELL * 0.10;
  ctx.fillStyle = '#0a120c';
  ctx.beginPath();
  ctx.arc(hp.x + ux * CELL * 0.15 + px * CELL * 0.17,
          hp.y + uy * CELL * 0.15 + py * CELL * 0.17, er, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath();
  ctx.arc(hp.x + ux * CELL * 0.15 - px * CELL * 0.17,
          hp.y + uy * CELL * 0.15 - py * CELL * 0.17, er, 0, Math.PI * 2); ctx.fill();
}

function drawEffects(now){
  S.effects = S.effects.filter(function(fx){ return now - fx.t < 400; });
  for (var i = 0; i < S.effects.length; i++){
    var fx = S.effects[i], e = (now - fx.t) / 400;
    ctx.beginPath();
    ctx.arc((fx.x + 0.5) * CELL, (fx.y + 0.5) * CELL, CELL * (0.35 + e * 1.5), 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(255,196,130,' + ((1 - e) * 0.55).toFixed(3) + ')';
    ctx.lineWidth = 2.5 * (1 - e) + 0.5;
    ctx.stroke();
  }
}

function drawOverlay(now){
  if (!S.alive){
    var a = Math.min(1, Math.max(0, (now - S.deathAt - 280) / 320));
    if (a <= 0) return;
    ctx.save(); ctx.globalAlpha = a;
    ctx.fillStyle = 'rgba(6,9,7,0.66)'; ctx.fillRect(0, 0, SIZE, SIZE);
    text(sp('GAME OVER'), SIZE / 2 - 30, 27, '#ff8a75');
    text('SCORE ' + S.score, SIZE / 2 + 8, 15, '#dcecd9');
    text(sp('PRESS START TO PLAY AGAIN'), SIZE / 2 + 40, 10, '#7c9180', 400);
    ctx.restore();
    return;
  }
  if (S.won){
    ctx.fillStyle = 'rgba(6,9,7,0.66)'; ctx.fillRect(0, 0, SIZE, SIZE);
    text(sp('YOU WIN'), SIZE / 2 - 22, 27, '#c8f7b8');
    text('SCORE ' + S.score, SIZE / 2 + 14, 15, '#dcecd9');
    return;
  }
  if (!S.running){
    rr(SIZE / 2 - 150, SIZE / 2 - 43, 300, 86, 10);
    ctx.fillStyle = 'rgba(7,10,8,0.86)'; ctx.fill();
    ctx.strokeStyle = 'rgba(255,255,255,0.05)'; ctx.lineWidth = 1; ctx.stroke();
    if (S.everStarted){
      text(sp('PAUSED'), SIZE / 2 - 11, 19, '#e6c47a');
      text(sp('SPACE OR START TO RESUME'), SIZE / 2 + 17, 9, '#7c9180', 400);
    } else {
      text(sp('PRESS START'), SIZE / 2 - 11, 19, '#c8f7b8');
      text(sp('OR PRESS AN ARROW KEY'), SIZE / 2 + 17, 9, '#7c9180', 400);
    }
  }
}

function draw(now){
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.fillStyle = '#0c110d';
  ctx.fillRect(0, 0, SIZE, SIZE);

  // death shake
  if (S.deathAt){
    var e = now - S.deathAt;
    if (e < 340){
      var amp = (1 - e / 340) * 5;
      ctx.translate(Math.sin(e * 0.09) * amp, Math.cos(e * 0.11) * amp);
    }
  }

  // faint checkerboard
  ctx.fillStyle = 'rgba(255,255,255,0.02)';
  for (var y = 0; y < ROWS; y++)
    for (var x = 0; x < COLS; x++)
      if ((x + y) & 1) ctx.fillRect(x * CELL, y * CELL, CELL, CELL);

  if (S.food) drawFood(now);
  drawSnake(now);
  drawEffects(now);

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  drawOverlay(now);
}

/* ---------- main loop (auto-advance + render) ---------- */
function loop(now){
  if (S.running && S.alive && !S.won && now - S.lastTick >= tickInterval()) tick();
  draw(now);
  requestAnimationFrame(loop);
}

/* ---------- buttons ---------- */
startBtn.addEventListener('click', function(){ startBtn.blur(); start(); });
pauseBtn.addEventListener('click', function(){ pauseBtn.blur(); pause(); });
resetBtn.addEventListener('click', function(){ resetBtn.blur(); reset(); });

/* ---------- keyboard ---------- */
var KEYMAP = {
  ArrowUp:'up', ArrowDown:'down', ArrowLeft:'left', ArrowRight:'right',
  w:'up', a:'left', s:'down', d:'right',
  W:'up', A:'left', S:'down', D:'right'
};
window.addEventListener('keydown', function(e){
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  var d = KEYMAP[e.key];
  if (d){
    e.preventDefault();
    setDir(d);
    if (e.isTrusted && !S.running && S.alive && !S.won && !S.everStarted) start();
    return;
  }
  if (e.key === ' ' || e.key === 'Enter'){
    if (!e.isTrusted) return;
    e.preventDefault();
    if (e.key === 'Enter'){
      if (!S.running) start();
    } else {
      if (S.running) pause();
      else if (S.alive && !S.won && S.everStarted) start();
    }
  }
});

/* ---------- touch (swipe) ---------- */
var tx = null, ty = null;
cv.addEventListener('touchstart', function(e){
  tx = e.touches[0].clientX; ty = e.touches[0].clientY;
}, {passive:true});
cv.addEventListener('touchmove', function(e){ e.preventDefault(); }, {passive:false});
cv.addEventListener('touchend', function(e){
  if (tx === null) return;
  var dx = e.changedTouches[0].clientX - tx, dy = e.changedTouches[0].clientY - ty;
  tx = null;
  if (Math.abs(dx) < 18 && Math.abs(dy) < 18) return;
  setDir(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left')
                                     : (dy > 0 ? 'down'  : 'up'));
  if (!S.running && S.alive && !S.won && !S.everStarted) start();
});

/* ---------- programmatic API (grading contract) ---------- */
window.game = {
  w: COLS,
  h: ROWS,
  reset:  function(){ reset(); },
  tick:   function(){ tick(); },
  setDir: function(d){ setDir(d); },
  setFood:function(x, y){ setFood(x, y); },
  snake:  function(){ return S.snake.map(function(s){ return [s.x, s.y]; }); },
  food:   function(){ return S.food ? [S.food.x, S.food.y] : null; },
  alive:  function(){ return S.alive; },
  score:  function(){ return S.score; }
};

/* ---------- boot ---------- */
reset();
requestAnimationFrame(loop);
})();
</script>
</body>
</html>
